var i=`0369-rosti`;var s=`world-0369`;var o=`CH`;var n=`western-europe`;var a=4;var r=37;var l={en:`Rösti`,ua:`Рьості`};var u={en:`A traditional Switzerland dish made with potato, chives. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Швейцарія. Основні інгредієнти: картопля, шніт-цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:9,i:[[`potato`,900,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 26 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 26 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:26,i:[[`clarified-butter`,110,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`chives`,18,`g`]]}];var g={slug:i,id:s,country:`CH`,region:n,servings:4,minutes:37,title:l,text:u,steps:d};export{o as country,g as default,s as id,r as minutes,n as region,a as servings,i as slug,d as steps,u as text,l as title};